    #[test]
    fn standard_stage_agent_dispatches_native_acquisition_tools() -> Result<(), ShellError> {
        let (engine_state, mut stack, root) = test_engine("stage-agent-acquisition-tools")?;
        fs::create_dir_all(root.join("pkg/sub")).expect("create fixture tree");
        fs::write(
            root.join("pkg/sub/frame_backend.c"),
            "alpha\nDG_DrawFrame();\nomega\n",
        )
        .expect("write fixture source");
        let source = format!(
            "{}\n{}",
            include_str!("../../../examples/scripts/standard_stage_agent.stone"),
            r#"
found = stage_agent_dispatch({
    "tool": "find",
    "input": {"path": ".", "name_glob": "*backend.c"},
})
searched = stage_agent_dispatch({
    "tool": "search",
    "input": {"path": ".", "needle": "DG_DrawFrame"},
})
ranged = stage_agent_dispatch({
    "tool": "read",
    "input": {
        "path": "pkg/sub/frame_backend.c",
        "start_line": 2,
        "end_line": 2,
    },
})
ending = stage_agent_dispatch({
    "tool": "read",
    "input": {"path": "pkg/sub/frame_backend.c", "tail_bytes": 6},
})
edited = stage_agent_dispatch({
    "tool": "edit",
    "input": {
        "path": "pkg/sub/frame_backend.c",
        "old": "alpha",
        "new": "beta",
    },
})
emit({
    "find_ok": found["ok"],
    "find_content": found["content"],
    "search_ok": searched["ok"],
    "search_content": searched["content"],
    "range_content": ranged["content"],
    "tail_content": ending["content"],
    "edit_ok": edited["ok"],
    "edit_replacements": edited["replacements"],
    "edited_content": read_text("pkg/sub/frame_backend.c"),
})
"#,
        );
        let program = lower_source(&source)?;
        let output =
            eval_program_with_output(&engine_state, &mut stack, &program, PipelineData::empty())?;
        let value = json::pipeline_to_json_value(output.pipeline, Span::unknown())?;
        assert_eq!(value["find_ok"], json_value!(true));
        assert!(value["find_content"]
            .as_str()
            .expect("find content")
            .contains("frame_backend.c"));
        assert_eq!(value["search_ok"], json_value!(true));
        assert!(value["search_content"]
            .as_str()
            .expect("search content")
            .contains("DG_DrawFrame"));
        assert_eq!(value["range_content"], json_value!("DG_DrawFrame();\n"));
        assert_eq!(value["tail_content"], json_value!("omega\n"));
        assert_eq!(value["edit_ok"], json_value!(true));
        assert_eq!(value["edit_replacements"], json_value!(1));
        assert_eq!(
            value["edited_content"],
            json_value!("beta\nDG_DrawFrame();\nomega\n")
        );
        cleanup_dir(&root);
        Ok(())
    }

    #[test]
    fn standard_stage_agent_applies_and_verifies_environment_transition() -> Result<(), ShellError>
    {
        let (engine_state, mut stack, root) = test_engine("stage-agent-environment-transition")?;
        let source = format!(
            "{}\n{}",
            include_str!("../../../examples/scripts/standard_stage_agent.stone"),
            r#"
missing = stage_agent_dispatch({
    "tool": "ensure_command",
    "input": {"command": "./never-created"},
})
provisioned = stage_agent_dispatch({
    "tool": "ensure_command",
    "input": {
        "command": "./fixture-command",
        "provision": {
            "argv": [
                "sh",
                "-c",
                "printf '#!/bin/sh\\nexit 0\\n' > fixture-command && chmod +x fixture-command",
            ],
        },
    },
})
retained = stage_agent_dispatch({
    "tool": "ensure_command",
    "input": {"command": "./fixture-command"},
})
emit({
    "missing_ok": missing["ok"],
    "missing_kind": missing["kind"],
    "missing_transition": missing["environment_transition"]["state"],
    "provisioned_ok": provisioned["ok"],
    "provisioned_kind": provisioned["kind"],
    "provisioned_transition": provisioned["environment_transition"]["state"],
    "provisioned_attempted": provisioned["environment_transition"]["attempted"],
    "verified": provisioned["verification"]["ok"],
    "retained_transition": retained["environment_transition"]["state"],
})
"#,
        );
        let program = lower_source(&source)?;
        let output =
            eval_program_with_output(&engine_state, &mut stack, &program, PipelineData::empty())?;
        let value = json::pipeline_to_json_value(output.pipeline, Span::unknown())?;
        assert_eq!(value["missing_ok"], json_value!(false));
        assert_eq!(value["missing_kind"], json_value!("capability_absent"));
        assert_eq!(value["missing_transition"], json_value!("not_requested"));
        assert_eq!(value["provisioned_ok"], json_value!(true));
        assert_eq!(value["provisioned_kind"], json_value!("capability_ready"));
        assert_eq!(value["provisioned_transition"], json_value!("applied"));
        assert_eq!(value["provisioned_attempted"], json_value!(true));
        assert_eq!(value["verified"], json_value!(true));
        assert_eq!(value["retained_transition"], json_value!("not_needed"));
        cleanup_dir(&root);
        Ok(())
    }

