    #[test]
    fn evaluates_common_python_shaped_ergonomics() -> Result<(), ShellError> {
        let (engine_state, mut stack, root) = test_engine("common-ergonomics")?;
        let program = lower_source(
            r#"line = "alpha,7"
missing = None
present = "value"
name, raw_score = line.split(",")
score = parse_int(raw_score, 0)
fallback = parse_float("bad", 1.5)
rows = [{"name": name, "score": score}, {"name": "skip", "score": 0}]
lookup = {row["name"]: row["score"] for row in rows if row["score"] != 0}
ordered = sorted([3, 1, 2])
parts = []
for key, value in items(lookup):
    parts.append(f"{key}:{value}")
i = 0
while i < 3:
    i += 1
def finish() -> None:
    return None
finished = finish()
emit({
    "message": f"{name}:{score}",
    "none_check": missing is None and present is not None,
    "finished": finished is None,
    "lookup_keys": keys(lookup),
    "lookup_value": get(lookup, "alpha", 0),
    "parts": parts,
    "ordered": ordered,
    "fallback": fallback,
    "i": i,
})
"#,
        )?;
        let output = eval_program(&engine_state, &mut stack, &program, PipelineData::empty())?;

        assert_eq!(
            json::pipeline_to_json_value(output, nu_protocol::Span::unknown())?,
            json_value!({
                "message": "alpha:7",
                "none_check": true,
                "finished": true,
                "lookup_keys": ["alpha"],
                "lookup_value": 7,
                "parts": ["alpha:7"],
                "ordered": [1, 2, 3],
                "fallback": 1.5,
                "i": 3,
            })
        );

        cleanup_dir(&root);
        Ok(())
    }

    #[test]
    fn typed_errors_match_in_order_and_keep_their_fields() -> Result<(), ShellError> {
        let (engine_state, mut stack, root) = test_engine("typed-errors")?;
        let source = r#"class ConfigError(ValueError):
    path: str
    retries: int = 0

out = {}
try:
    raise ConfigError("bad config", path="/etc/app")
except (KeyError, IndexError) as error:
    out["wrong"] = error.type
except ValueError as error:
    out["config"] = {"type": error.type, "message": error.message, "path": error.path, "retries": error.retries}
except Exception as error:
    out["too_broad"] = error.type
try:
    try:
        raise ConfigError("inner", path="p")
    except Exception as error:
        raise
except ConfigError as again:
    out["reraised"] = [again.type, again.path]
try:
    raise NotImplementedError
except RuntimeError as error:
    out["bare_name"] = [error.type, error.message]
try:
    read_text("missing.txt")
except FileNotFoundError as error:
    out["missing"] = [error.type, error.code]
try:
    value = {}["k"]
except LookupError as error:
    out["key"] = error.type
try:
    value = [1][5]
except IndexError as error:
    out["index"] = error.type
try:
    value = 1 // 0
except ArithmeticError as error:
    out["zero"] = error.type
try:
    value = int("x")
except ValueError as error:
    out["parse"] = error.type
try:
    value = 1 + "a"
except TypeError as error:
    out["add"] = error.type
try:
    try:
        value = 1 // 0
    except KeyError as error:
        out["not_reached"] = True
except ZeroDivisionError as error:
    out["propagated"] = error.type
try:
    raise {"message": "m", "code": "c", "detail": {"k": 1}}
except Exception as error:
    out["record"] = [error.type, error.declared_code, error.detail]
try:
    read_text("missing.txt")
except ToolError:
    out["swallowed"] = True
emit(out)
"#;
        let program = lower_source(source)?;
        let mut session = StoneSession::default();
        let output = eval_program_with_output_and_session(
            &engine_state,
            &mut stack,
            &program,
            PipelineData::empty(),
            Some(&mut session),
            Some(source),
            None,
        )?;
        assert_eq!(
            json::pipeline_to_json_value(output.pipeline, nu_protocol::Span::unknown())?,
            json_value!({
                "config": {"type": "ConfigError", "message": "bad config", "path": "/etc/app", "retries": 0},
                "reraised": ["ConfigError", "p"],
                "bare_name": ["NotImplementedError", ""],
                "missing": ["FileNotFoundError", "stone_io_error"],
                "key": "KeyError",
                "index": "IndexError",
                "zero": "ZeroDivisionError",
                "parse": "ValueError",
                "add": "TypeError",
                "propagated": "ZeroDivisionError",
                "record": ["Exception", "c", {"k": 1}],
                "swallowed": true,
            })
        );
        assert_eq!(
            output.diagnostics["errors"]["swallowed_tool_errors"],
            json_value!(1)
        );
        assert_eq!(
            output.diagnostics["errors"]["last_swallowed"]["type"],
            json_value!("FileNotFoundError")
        );
        // The class persists in the session like a function.
        assert!(session.functions.contains_key("ConfigError"));
        cleanup_dir(&root);
        Ok(())
    }

    #[test]
    fn attempt_over_errors_are_control_stops_but_denials_are_not() {
        // The Gateway refuses effects from a finished or cancelled attempt
        // with these messages; no `except` handler may run for them.
        assert!(super::is_attempt_over_error(&super::stone_error(
            "gateway rpc",
            "task attempt a-1 is terminal (cancelled)"
        )));
        assert!(super::is_attempt_over_error(&super::stone_error(
            "gateway rpc",
            "task attempt a-1 already reported a result; no new compute may be dispatched"
        )));
        assert!(super::is_attempt_over_error(&super::budget_stop_error(
            "the attempt's tool_calls budget is used up".to_string()
        )));
        // An ordinary failure, including a refused call, stays catchable.
        assert!(!super::is_attempt_over_error(&super::stone_error(
            "gateway rpc",
            "connection refused"
        )));
    }

    #[test]
    fn denials_are_counted_and_program_raises_stay_catchable() -> Result<(), ShellError> {
        let (engine_state, mut stack, root) = test_engine("control-stops")?;
        let source = r#"out = {}
result = run(["printf", "x"], hooks={"pre": lambda step: {"allow": False, "reason": "outside policy"}})
out["vetoed"] = [result.ok, result.kind]
try:
    raise ValueError("attempt a-1 is terminal (cancelled)")
except ValueError as error:
    out["own_raise_caught"] = True
emit(out)
"#;
        let program = lower_source(source)?;
        let output = eval_program_with_output_and_session(
            &engine_state,
            &mut stack,
            &program,
            PipelineData::empty(),
            None,
            Some(source),
            None,
        )?;
        assert_eq!(
            json::pipeline_to_json_value(output.pipeline, nu_protocol::Span::unknown())?,
            json_value!({"vetoed": [false, "policy_rejected"], "own_raise_caught": true})
        );
        assert_eq!(output.diagnostics["denials"]["count"], json_value!(1));
        assert_eq!(
            output.diagnostics["denials"]["last"]["reason"],
            json_value!("outside policy")
        );
        cleanup_dir(&root);
        Ok(())
    }

