    #[test]
    fn dicts_use_brackets_and_host_results_are_records() -> Result<(), ShellError> {
        let (engine_state, mut stack, _root) = test_engine("dict-record-access")?;
        let program = lower_source(
            r#"d = {"keys": 1, "xs": [1]}
errors = []
for read in [lambda: d.keys, lambda: d.missing]:
    try:
        read()
    except AttributeError as e:
        errors.append(str(e))
r = run(["true"])
try:
    r["exit_code"]
except TypeError as e:
    errors.append(str(e))
get(d, "xs").append(2)
seen = []
def post(step):
    value = get(step.outcome, "value", None)
    seen.append([value.exit_code == step.outcome.value.exit_code, "exit_code" in value])
    return None
run(["true"], hooks={"post": post})
emit({"errors": errors, "code": r.exit_code, "has": ["exit_code" in r, "nope" in r],
      "xs": d["xs"], "missing": get(d, "zz", 5), "seen": seen, "type": type(r)})"#,
        )?;
        let output = eval_program(&engine_state, &mut stack, &program, PipelineData::empty())?;
        let value = json::pipeline_to_json_value(output, nu_protocol::Span::unknown())?;
        let errors = value["errors"].as_array().expect("errors");
        assert_eq!(errors.len(), 3, "{value}");
        assert!(errors[0].as_str().unwrap().contains(r#"write `["keys"]` instead of `.keys`"#), "{value}");
        assert!(errors[1].as_str().unwrap().contains("a dict has no attribute `missing`"), "{value}");
        assert!(errors[2].as_str().unwrap().contains("cannot subscript a RunResult record"), "{value}");
        assert_eq!(value["code"], json_value!(0));
        assert_eq!(value["has"], json_value!([true, false]));
        assert_eq!(value["xs"], json_value!([1, 2]));
        assert_eq!(value["missing"], json_value!(5));
        assert_eq!(value["seen"], json_value!([[true, true]]));
        assert_eq!(value["type"], json_value!("RunResult"));
        Ok(())
    }

    #[test]
    fn tuples_and_sets_have_python_meaning() -> Result<(), ShellError> {
        let (engine_state, mut stack, root) = test_engine("tuples-sets")?;
        let program = lower_source(
            r#"t = (1, "a", [2])
a, b, c = t
c.append(3)
def pair():
    return 1, 2
x = set([1, 2, 3])
y = set([2, 3, 4])
seen = set()
seen.add((1, 2))
seen.add((1, 2))
seen.discard((9, 9))
d = {"k": set()}
d["k"].add("v")
emit({
    "tuple": [repr(t), repr((1,)), repr(()), len(t), t[-1], repr(t[1:]), type(t), repr(pair()), repr((1, 2) + (3,)), (1, 2, 1).count(1), (1, 2).index(2)],
    "tuple_cmp": [(1, 2) == (1, 2), (1, 2) < (1, 3), 2 in (1, 2), isinstance(t, tuple), isinstance(t, list)],
    "set": [repr(x | y), repr(x & y), repr(x - y), repr(x ^ y), set([1, 2]) == set([2, 1]), x <= set([1, 2, 3, 4]), 1 in x, repr(set()), type(x), repr(x.union([9]))],
    "pairs": [len(seen), (1, 2) in seen, repr(seen)],
    "json": [t, x, d],
})"#,
        )?;
        let output = eval_program(&engine_state, &mut stack, &program, PipelineData::empty())?;
        let value = json::pipeline_to_json_value(output, nu_protocol::Span::unknown())?;
        assert_eq!(
            value["tuple"],
            json_value!(["(1, 'a', [2, 3])", "(1,)", "()", 3, [2, 3], "('a', [2, 3])", "tuple", "(1, 2)", "(1, 2, 3)", 2, 1])
        );
        assert_eq!(value["tuple_cmp"], json_value!([true, true, true, true, false]));
        assert_eq!(
            value["set"],
            json_value!(["{1, 2, 3, 4}", "{2, 3}", "{1}", "{1, 4}", true, true, true, "set()", "set", "{1, 2, 3, 9}"])
        );
        assert_eq!(value["pairs"], json_value!([1, true, "{(1, 2)}"]));
        // Tuples and sets become JSON arrays where values leave the program.
        assert_eq!(value["json"], json_value!([[1, "a", [2, 3]], [1, 2, 3], {"k": ["v"]}]));

        for (source, needle) in [
            ("emit((1, 2) == [1, 2])", "comparing a tuple with a list"),
            ("emit(set([1]) == [1])", "comparing a set with a list"),
            ("t = (1, 2)\nt[0] = 5", "a tuple cannot change"),
            ("t = (1,)\nt.append(2)", "tuples cannot change"),
            ("emit(set([[1]]))", "unhashable type: 'list'"),
            ("emit(set([1, True]))", "keeps bool and int apart"),
            ("s = set([1])\ns.remove(2)", "use discard()"),
            ("emit(set([1])[0])", "cannot be indexed"),
            ("emit([1] | [2])", "set(a) | set(b)"),
            ("xs = []\nxs.add(1)", "use xs.append(x)"),
            ("emit(set([1]) + set([2]))", "use `a | b`"),
            ("emit((1, 2) + [3])", "a tuple joins only another tuple"),
        ] {
            let program = lower_source(source)?;
            let err = eval_program(&engine_state, &mut stack, &program, PipelineData::empty())
                .expect_err(source);
            assert!(format!("{err:?}").contains(needle), "{source}: {err:?}");
        }
        cleanup_dir(&root);
        Ok(())
    }

    #[test]
    fn comparisons_that_mix_bool_and_number_raise() -> Result<(), ShellError> {
        let (engine_state, mut stack, root) = test_engine("bool-number")?;
        let program = lower_source(
            r#"emit([True == True, 1 == 1.0, [1, 1.0].count(1), [1, 2] == [1, 2, 3], None == 0, "1" == 1, False in [False], [1, 2].index(2)])"#,
        )?;
        let output = eval_program(&engine_state, &mut stack, &program, PipelineData::empty())?;
        let value = json::pipeline_to_json_value(output, nu_protocol::Span::unknown())?;
        assert_eq!(value, json_value!([true, true, 2, false, false, false, true, 1]));

        for source in [
            "emit(True == 1)",
            "emit(1 != True)",
            "emit(0 == False)",
            "emit(1.0 == True)",
            "emit([True] == [1])",
            r#"emit({"a": True} == {"a": 1})"#,
            "emit(1 in [True, 2])",
            "emit([1, 2].index(True))",
            "emit([1, True].count(1))",
            "flags = [True, False]\nhits = 0\nfor i in range(3):\n    if i in flags:\n        hits += 1\nemit(hits)\n",
        ] {
            let program = lower_source(source)?;
            let err = eval_program(&engine_state, &mut stack, &program, PipelineData::empty())
                .expect_err(source);
            let text = format!("{err:?}");
            assert!(text.contains("keeps bool and int apart"), "{source}: {text}");
            assert!(text.contains("int(flag) or bool(count)"), "{source}: {text}");
        }
        cleanup_dir(&root);
        Ok(())
    }

    #[test]
    fn expression_operator_edge_errors_do_not_return_values() -> Result<(), ShellError> {
        let cases = [
            ("div-zero", r#"emit(1 / 0)"#, "division by zero"),
            ("floor-div-zero", r#"emit(1 // 0)"#, "division by zero"),
            ("mod-zero", r#"emit(1 % 0)"#, "modulo by zero"),
            (
                "add-overflow",
                r#"emit(9223372036854775807 + 1)"#,
                "integer addition overflow",
            ),
            (
                "sub-overflow",
                r#"emit((0 - 9223372036854775807) - 2)"#,
                "integer subtraction overflow",
            ),
            (
                "mul-overflow",
                r#"emit(9223372036854775807 * 2)"#,
                "integer multiplication overflow",
            ),
            (
                "neg-overflow",
                r#"emit(-((0 - 9223372036854775807) - 1))"#,
                "integer negation overflow",
            ),
            (
                "floor-div-overflow",
                r#"emit(((0 - 9223372036854775807) - 1) // -1)"#,
                "integer floor division overflow",
            ),
            (
                "mod-overflow",
                r#"emit(((0 - 9223372036854775807) - 1) % -1)"#,
                "integer floor division overflow",
            ),
            ("bad-add", r#"emit("1" + 1)"#, "cannot add"),
            ("bad-sub", r#"emit("1" - 1)"#, "cannot subtract"),
            ("bad-mul", r#"emit("1" * 1.5)"#, "cannot multiply"),
            ("bad-div", r#"emit("1" / 2)"#, "cannot divide"),
            ("bad-floor-div", r#"emit("1" // 2)"#, "cannot divide"),
            ("bad-mod", r#"emit("1" % 2)"#, "cannot modulo"),
            ("bad-order", r#"emit("1" < 2)"#, "cannot order"),
            (
                "bad-membership",
                r#"emit(1 in 2)"#,
                "cannot test membership",
            ),
            (
                "negative-shift",
                r#"emit(1 << -1)"#,
                "shift count must be non-negative",
            ),
            (
                "oversized-shift",
                r#"emit(1 << 100)"#,
                "shift count is too large",
            ),
            ("bad-unary-minus", r#"emit(-"not-number")"#, "cannot negate"),
            ("bad-bitwise", r#"emit("1" & 1)"#, "expected int, got str"),
            ("bad-bitwise-invert", r#"emit(~"1")"#, "expected int, got str"),
        ];

        for (name, source, expected) in cases {
            let (engine_state, mut stack, root) = test_engine(&format!("expr-edge-{name}"))?;
            let program = lower_source(source)?;
            let error = eval_program(&engine_state, &mut stack, &program, PipelineData::empty())
                .expect_err(name);
            let text = format!("{error:?}");
            assert!(text.contains(expected), "{name}: {text}");
            cleanup_dir(&root);
        }

        Ok(())
    }

    #[test]
    fn unsupported_expression_ops_in_hot_loop_match_baseline_by_fallback() -> Result<(), ShellError>
    {
        assert_hot_loop_matches_baseline(
            "hot-loop-fallback-div-mod-neg",
            r#"total = 0.0
for n in [2, 4, 6]:
    total = total + (n / 2)
    total = total + (n % 4)
    total = total + -1
emit(total)
"#,
            &[],
        )?;

        assert_hot_loop_matches_baseline(
            "hot-loop-fallback-comparison-bool",
            r#"seen = []
for n in [1, 2, 3, 4]:
    if (n > 1 and n <= 3) or n == 4:
        seen.append(n)
emit(seen)
"#,
            &[],
        )?;

        let source = r#"total = 0.0
for n in [2, 4, 6]:
    total = total + (n / 2)
emit(total)
"#;
        let (engine_state, mut stack, root) = test_engine("hot-loop-fallback-div-diagnostics")?;
        let program = lower_source(source)?;
        let output = eval_program_with_options(
            &engine_state,
            &mut stack,
            &program,
            PipelineData::empty(),
            EvalOptions {
                hot_loop_enabled: true,
                hot_loop_vm_interpreter: true,
                hot_loop_validate_snapshot: false,
                session: None,
            },
        )?;

        assert_eq!(
            json::pipeline_to_json_value(output.pipeline, nu_protocol::Span::unknown())?,
            json_value!(6.0)
        );
        assert_eq!(
            output.diagnostics["hot_loop"]["generic_vm_loops_executed"],
            json_value!(0)
        );

        cleanup_dir(&root);
        Ok(())
    }

    #[test]
    fn negative_semantic_tests_fail_instead_of_returning_wrong_values() -> Result<(), ShellError> {
        let (engine_state, mut stack, root) = test_engine("negative-semantics")?;
        let missing_key = lower_source(r#"emit({"a": 1}["b"])"#)?;
        let error = eval_program(
            &engine_state,
            &mut stack,
            &missing_key,
            PipelineData::empty(),
        )
        .expect_err("missing key should fail");
        let text = format!("{error:?}");
        assert!(
            text.contains("no key") || text.contains("cannot find column"),
            "{text}"
        );

        let bad_type = lower_source(
            r#"total = 0
for value in ["not-int"]:
    total += int(value)
emit(total)
"#,
        )?;
        let error = eval_program_hot_loop(&engine_state, &mut stack, &bad_type)
            .expect_err("bad int conversion should fail");
        let text = format!("{error:?}");
        assert!(
            text.contains("invalid digit") || text.contains("int"),
            "{text}"
        );

        for (name, source, expected) in [
            (
                "bad-augassign-sub",
                r#"value = "1"
value -= 1
"#,
                "cannot subtract",
            ),
            (
                "bad-augassign-bitwise",
                r#"value = "1"
value |= 1
"#,
                "expected int, got str",
            ),
            (
                "bad-augassign-zero-div",
                r#"value = 1
value /= 0
"#,
                "division by zero",
            ),
            (
                "bad-augassign-zero-mod",
                r#"value = 1
value %= 0
"#,
                "modulo by zero",
            ),
            (
                "bad-augassign-overflow",
                r#"value = 9223372036854775807
value += 1
"#,
                "integer addition overflow",
            ),
            ("bad-any-non-iterable", r#"any(1)"#, "cannot iterate int"),
            (
                "bad-default-type",
                r#"def f(value: int = "bad") -> int:
    return value
f()
"#,
                "argument `value` expected int",
            ),
        ] {
            let program = lower_source(source)?;
            let error = eval_program(&engine_state, &mut stack, &program, PipelineData::empty())
                .expect_err(name);
            let text = format!("{error:?}");
            assert!(text.contains(expected), "{name}: {text}");
        }

        cleanup_dir(&root);
        Ok(())
    }

